// ftx -- forward DCT4 .. DCT64, ADST8 and ADST16 butterflies of the AV1 encoder as
// straight-line code, and the encoder's tables  [src/img/av1_ftx.s]
//
// GENERATED by tools/gen_av1ftx.py from the assembly (itself generated by tools/av1_gen.py
// from tools/av1_enc_ref.py); do not edit.
//
//   dct4(t)     4 butterflies on t: [i32; 4]
//   dct8(t)     13 butterflies on t: [i32; 8]
//   dct16(t)    37 butterflies on t: [i32; 16]
//   dct32(t)    97 butterflies on t: [i32; 32]
//   dct64(t)    241 butterflies on t: [i32; 64]
//   adst8(t)    16 butterflies on t: [i32; 8]
//   adst16(t)   44 butterflies on t: [i32; 16]
//   COST        u16[1024] Q8 bits of a symbol of probability (i + 0.5) / 1024  [av1e_cost]
//   KQ          u32[TX_SIZES_ALL] quantizer scale K (Q16) per transform size  [av1e_kq]
//
// t in place, no clamping (exact for 8 / 10-bit residuals); the permutations are the
// caller's (DCT: result i belongs to coefficient brev(n, i); ADST: input index outp(i) with
// the sign of odd i, result i to coefficient i - 1 (odd i) / N - 1 - i).  r(): a rotation
// with 64-bit products, h(): Ta + Tb, Ta - Tb (32-bit, wrapping as the assembly's lea / sub).

// h(t, a, b): t[a], t[b] = t[a] + t[b], t[a] - t[b]
#[inline(always)]
fn h<const N: usize>(t: &mut [i32; N], a: usize, b: usize) {
    let x = t[a];
    let y = t[b];
    t[a] = x.wrapping_add(y);
    t[b] = x.wrapping_sub(y);
}

// r(t, a, b, u, v, c, s, s2, c2): x = t[u], y = t[v];
// t[a] = (x * c - y * s + 2048) >> 12, t[b] = (x * s2 + y * c2 + 2048) >> 12
#[inline(always)]
#[allow(clippy::too_many_arguments)]
fn r<const N: usize>(t: &mut [i32; N], a: usize, b: usize, u: usize, v: usize, c: i64, s: i64, s2: i64, c2: i64) {
    let x = t[u] as i64;
    let y = t[v] as i64;
    let p = (x.wrapping_mul(c).wrapping_sub(y.wrapping_mul(s)).wrapping_add(2048)) >> 12;
    let q = (x.wrapping_mul(s2).wrapping_add(y.wrapping_mul(c2)).wrapping_add(2048)) >> 12;
    t[a] = p as i32;
    t[b] = q as i32;
}

